    "HouseConfig: seed, recipe, pack, mode, era, size, variation, wealth, overrides (roof, floors, frame, infill, coating, cladding, courtyard_ratio, roof_pitch_deg…). Missing values inherit the settlement recipe. Native placement determines orientation from parcel access.": "HouseConfig: semilla, receta, paquete, modo, era, tamaño, variación, riqueza, anulaciones (techo, pisos, marco, relleno, revestimiento, revestimiento, relación_patio, grado_inclinación del techo...). Los valores faltantes heredan la receta de liquidación. La ubicación nativa determina la orientación desde el acceso a la parcela.",
