    "Choose a tool, then work on the map. Edits apply directly to this map and are saved with the complete project; regenerating the region replaces them.": "Elija una herramienta y luego trabaje en el mapa. Las ediciones se aplican directamente a este mapa y se guardan con el proyecto completo; la regeneración de la región los reemplaza.",
    "Drag a road to move it. Drag a point to reshape it; double-click a point to remove it. Press Esc to finish.": "Arrastra una carretera para moverla. Arrastre un punto para remodelarlo; haga doble clic en un punto para eliminarlo. Presione Esc para finalizar.",
    "Click to add points. Click the last point again or press Enter to finish; Esc cancels. Ends snap to junctions, settlements and roads.": "Haga clic para agregar puntos. Haga clic nuevamente en el último punto o presione Entrar para finalizar; Esc se cancela. Los extremos se enganchan en cruces, asentamientos y carreteras.",
