    "Keep the full cultural form, or translate only generic place terms. Proper names stay unchanged.": "Mantenga la forma cultural completa o traduzca sólo términos de lugares genéricos. Los nombres propios permanecen sin cambios.",
    "Choose format and export…": "Elija formato y exporte…",
    "Regional network": "Red regional",
    "Click the start, then the destination. The route follows terrain and regional road settings. Esc cancels.": "Haga clic en el inicio y luego en el destino. La ruta sigue el terreno y la configuración de las carreteras regionales. Esc se cancela.",
    "Route drawing": "Dibujo de ruta",
    "Automatic · terrain": "Automático · terreno",
    "NF4 B75 · quality and speed": "NF4 B75 · calidad y rapidez",
    "Upstream CUDA evaluation on seven scenes: mean absolute difference of 22.15–24.06 m from the original BF16 base, depending on detail level. This measures agreement with that model, not accuracy against real terrain, and does not certify browser output. Excess fine grain on plains and coastal differences remain.": "Evaluación CUDA ascendente en siete escenas: diferencia absoluta media de 22,15 a 24,06 m con respecto a la base BF16 original, según el nivel de detalle. Esto mide la concordancia con ese modelo, no la precisión frente al terreno real, y no certifica la salida del navegador. En las llanuras y en las diferencias costeras persiste un exceso de grano fino.",
    "Compression reduces download size. Weights are decoded into FP16 or FP32 for GPU inference: neither faster generation nor a 150 MB GPU footprint is guaranteed. There is no B75-specific WebGPU speed benchmark or certified minimum hardware configuration.": "La compresión reduce el tamaño de la descarga. Los pesos se decodifican en FP16 o FP32 para la inferencia de GPU: no se garantiza una generación más rápida ni una huella de GPU de 150 MB. No existe un punto de referencia de velocidad WebGPU específico para B75 ni una configuración de hardware mínima certificada.",
    "Upstream release and evaluation ↗": "Lanzamiento y evaluación upstream ↗",
    "Coarse · initial terrain": "Grueso · terreno inicial",
    "Base · terrain detail": "Base · detalle del terreno",
    "Decoder · elevations": "Decodificador · elevaciones",
