    "Persistent storage granted. You can still remove models or clear site data.": "Almacenamiento persistente concedido. Aún puedes eliminar modelos o borrar datos del sitio.",
    "Storage is not protected from automatic eviction. Request persistent storage to improve retention; the browser may refuse.": "El almacenamiento no está protegido contra el desalojo automático. Solicitar almacenamiento persistente para mejorar la retención; el navegador puede negarse.",
    "Persistent storage requests are unavailable in this browser.": "Las solicitudes de almacenamiento persistente no están disponibles en este navegador.",
    "The browser did not grant persistent storage. Downloaded files remain available but can be evicted.": "El navegador no permitió almacenamiento persistente. Los archivos descargados permanecen disponibles pero pueden ser desalojados.",
