    "These files are not used by the current catalogue. They may belong to another model address or version.": "Estos archivos no son utilizados por el catálogo actual. Pueden pertenecer a otra dirección o versión del modelo.",
    "Catalogue unavailable. Check the model address and connection. Previously downloaded files are listed below when browser storage is accessible.": "Catálogo no disponible. Verifique la dirección del modelo y la conexión. Los archivos descargados anteriormente se enumeran a continuación cuando se puede acceder al almacenamiento del navegador.",
    "Showing the saved catalogue: the server could not be reached or did not provide a valid catalogue.": "Mostrando el catálogo guardado: no se pudo contactar con el servidor o no proporcionó un catálogo válido.",
    "Unable to access or save browser files. Check available disk space and site storage permissions, then try again. This download has not been confirmed as saved.": "No se puede acceder ni guardar archivos del navegador. Verifique el espacio disponible en disco y los permisos de almacenamiento del sitio, luego inténtelo nuevamente. Esta descarga no ha sido confirmada como guardada.",
    "The model is incomplete or failed its integrity check. It was not saved; try downloading again.": "El modelo está incompleto o no pasó la verificación de integridad. No fue salvo; intenta descargar de nuevo.",
    "Download failed. Check your connection and model address, then retry. Completed downloads are retained.": "La descarga falló. Verifique su conexión y dirección de modelo, luego vuelva a intentarlo. Las descargas completadas se conservan.",
    "Models verified and saved on this device.": "Modelos verificados y guardados en este dispositivo.",
    "Downloaded files removed. A model already loaded in GPU memory can continue until the engine is released.": "Archivos descargados eliminados. Un modelo ya cargado en la memoria de la GPU puede continuar hasta que se lance el motor.",
