    "The classic TypeScript engine supports 600–40,000 m. Select the Rust engine for 500–100,000 m.": "El motor TypeScript clásico admite entre 600 y 40 000 m. Seleccione el motor Rust para 500-100 000 m.",
    "CPU execution conflicts with explicit GPU terrain controls. Choose automatic/GPU or reset those controls.": "La ejecución de la CPU entra en conflicto con los controles explícitos del terreno de la GPU. Elija automático/GPU o restablezca esos controles.",
