    "Prepare browser generation now. Downloads are shared with the terrain engine; no GPU is needed to download them.": "Prepare la generación del navegador ahora. Las descargas se comparten con el motor de terreno; no se necesita GPU para descargarlos.",
    "Stored on this device, for this browser profile and site address. Clearing site data removes the models. These files do not install Python/CUDA models.": "Almacenado en este dispositivo, para este perfil de navegador y dirección de sitio. Al borrar los datos del sitio se eliminan los modelos. Estos archivos no instalan modelos Python/CUDA.",
    "Downloaded weights still need WebGPU and must be loaded into GPU memory at each new session. This does not make the whole application available offline.": "Los pesos descargados aún necesitan WebGPU y deben cargarse en la memoria de la GPU en cada nueva sesión. Esto no hace que toda la aplicación esté disponible sin conexión.",
    "NF4 B75 is the distilled base network: branch B, exponential moving-average weights at 75,000 training steps, 4-bit weight compression and a two-step solver. B75 names the training checkpoint.": "NF4 B75 es la red base destilada: rama B, pesos de promedio móvil exponencial en 75.000 pasos de entrenamiento, compresión de peso de 4 bits y un solucionador de dos pasos. B75 nombra el punto de control de entrenamiento.",
