    "These files are not used by the current catalogue. They may belong to another model address or version.": "Esses arquivos não são usados pelo catálogo atual. Eles podem pertencer a outro endereço ou versão de modelo.",
    "Catalogue unavailable. Check the model address and connection. Previously downloaded files are listed below when browser storage is accessible.": "Catálogo indisponível. Verifique o endereço do modelo e a conexão. Os arquivos baixados anteriormente são listados abaixo quando o armazenamento do navegador está acessível.",
    "Showing the saved catalogue: the server could not be reached or did not provide a valid catalogue.": "Mostrando o catálogo salvo: o servidor não foi encontrado ou não forneceu um catálogo válido.",
    "Unable to access or save browser files. Check available disk space and site storage permissions, then try again. This download has not been confirmed as saved.": "Não é possível acessar ou salvar arquivos do navegador. Verifique o espaço em disco disponível e as permissões de armazenamento do site e tente novamente. Este download não foi confirmado como salvo.",
    "The model is incomplete or failed its integrity check. It was not saved; try downloading again.": "O modelo está incompleto ou falhou na verificação de integridade. Não foi salvo; tente baixar novamente.",
    "Download failed. Check your connection and model address, then retry. Completed downloads are retained.": "Falha no download. Verifique sua conexão e endereço do modelo e tente novamente. Os downloads concluídos são retidos.",
    "Models verified and saved on this device.": "Modelos verificados e salvos neste dispositivo.",
    "Downloaded files removed. A model already loaded in GPU memory can continue until the engine is released.": "Arquivos baixados removidos. Um modelo já carregado na memória da GPU pode continuar até que o mecanismo seja liberado.",
    "Download cancelled. Completed models are retained; partial files are not saved.": "Download cancelado. Os modelos concluídos são mantidos; arquivos parciais não são salvos.",
    "Downloading": "Baixando",
    "Verifying integrity": "Verificando a integridade",
    "Saving on this device": "Salvando neste dispositivo",
    "Required model files": "Arquivos de modelo necessários",
