    "Regional composition": "Composição regional",
    "NF4 B75 · quality and speed": "NF4 B75 · qualidade e rapidez",
    "Upstream CUDA evaluation on seven scenes: mean absolute difference of 22.15–24.06 m from the original BF16 base, depending on detail level. This measures agreement with that model, not accuracy against real terrain, and does not certify browser output. Excess fine grain on plains and coastal differences remain.": "Avaliação CUDA upstream em sete cenas: diferença média absoluta de 22,15–24,06 m da base BF16 original, dependendo do nível de detalhe. Isso mede a concordância com esse modelo, não a precisão em relação ao terreno real e não certifica a saída do navegador. O excesso de grãos finos permanece nas planícies e nas diferenças costeiras.",
    "Compression reduces download size. Weights are decoded into FP16 or FP32 for GPU inference: neither faster generation nor a 150 MB GPU footprint is guaranteed. There is no B75-specific WebGPU speed benchmark or certified minimum hardware configuration.": "A compactação reduz o tamanho do download. Os pesos são decodificados em FP16 ou FP32 para inferência de GPU: nem a geração mais rápida nem o uso de GPU de 150 MB são garantidos. Não há benchmark de velocidade WebGPU específico para B75 ou configuração mínima de hardware certificada.",
    "Upstream release and evaluation ↗": "Liberação e avaliação upstream ↗",
