    "Prepare browser generation now. Downloads are shared with the terrain engine; no GPU is needed to download them.": "Prepare a geração do navegador agora. Os downloads são compartilhados com o mecanismo de terreno; nenhuma GPU é necessária para baixá-los.",
    "Stored on this device, for this browser profile and site address. Clearing site data removes the models. These files do not install Python/CUDA models.": "Armazenado neste dispositivo, para este perfil de navegador e endereço do site. A limpeza dos dados do site remove os modelos. Esses arquivos não instalam modelos Python/CUDA.",
    "Downloaded weights still need WebGPU and must be loaded into GPU memory at each new session. This does not make the whole application available offline.": "Os pesos baixados ainda precisam de WebGPU e devem ser carregados na memória da GPU a cada nova sessão. Isso não disponibiliza todo o aplicativo offline.",
    "NF4 B75 is the distilled base network: branch B, exponential moving-average weights at 75,000 training steps, 4-bit weight compression and a two-step solver. B75 names the training checkpoint.": "NF4 B75 é a rede base destilada: ramo B, pesos médios móveis exponenciais em 75.000 etapas de treinamento, compressão de peso de 4 bits e um solucionador de duas etapas. B75 nomeia o ponto de verificação de treinamento.",
