    "Upstream CUDA evaluation on seven scenes: mean absolute difference of 22.15–24.06 m from the original BF16 base, depending on detail level. This measures agreement with that model, not accuracy against real terrain, and does not certify browser output. Excess fine grain on plains and coastal differences remain.": "对七个场景的上游 CUDA 评估：与原始 BF16 基础的平均绝对差异为 22.15–24.06 m，具体取决于细节级别。这衡量与该模型的一致性，而不是针对真实地形的准确性，并且不验证浏览器输出。平原细粮过剩和沿海差异依然存在。",
    "Compression reduces download size. Weights are decoded into FP16 or FP32 for GPU inference: neither faster generation nor a 150 MB GPU footprint is guaranteed. There is no B75-specific WebGPU speed benchmark or certified minimum hardware configuration.": "压缩可减少下载大小。权重被解码为 FP16 或 FP32 以进行 GPU 推理：既不能保证更快的生成速度，也不能保证 150 MB GPU 占用空间。没有特定于 B75 的 WebGPU 速度基准或经过认证的最低硬件配置。",
    "Upstream release and evaluation ↗": "上游发布和评估 ↗",
