    "Catalogue unavailable. Check the model address and connection. Previously downloaded files are listed below when browser storage is accessible.": "目录不可用。检查型号地址和连接。当浏览器存储可访问时，以前下载的文件会在下面列出。",
    "Showing the saved catalogue: the server could not be reached or did not provide a valid catalogue.": "显示已保存的目录：无法访问服务器或未提供有效的目录。",
    "Unable to access or save browser files. Check available disk space and site storage permissions, then try again. This download has not been confirmed as saved.": "无法访问或保存浏览器文件。检查可用磁盘空间和站点存储权限，然后重试。此下载尚未确认已保存。",
