    "Stored on this device, for this browser profile and site address. Clearing site data removes the models. These files do not install Python/CUDA models.": "存储在此设备上的浏览器配置文件和站点地址。清除站点数据会删除模型。这些文件不安装 Python/CUDA 模型。",
    "Downloaded weights still need WebGPU and must be loaded into GPU memory at each new session. This does not make the whole application available offline.": "下载的权重仍然需要 WebGPU，并且必须在每个新会话中加载到 GPU 内存中。这不会使整个应用程序离线可用。",
    "NF4 B75 is the distilled base network: branch B, exponential moving-average weights at 75,000 training steps, 4-bit weight compression and a two-step solver. B75 names the training checkpoint.": "NF4 B75 是经过提炼的基础网络：分支 B、75,000 个训练步骤的指数移动平均权重、4 位权重压缩和两步求解器。 B75 命名训练检查点。",
