    "Click the start, then the destination. The route follows terrain and regional road settings. Esc cancels.": "انقر فوق ابدأ، ثم الوجهة. يتبع المسار إعدادات التضاريس والطرق الإقليمية. إلغاء Esc.",
    "Route drawing": "رسم الطريق",
