    "No road route could be found between these points.": "ولا يمكن العثور على طريق طريق بين هذه النقاط.",
    "Edit roads": "تحرير الطرق",
    "Draw a road": "ارسم الطريق",
    "Delete a river": "حذف النهر",
    "Choose a tool, then work on the map. Edits apply directly to this map and are saved with the complete project; regenerating the region replaces them.": "اختر أداة، ثم اعمل على الخريطة. تنطبق التعديلات مباشرة على هذه الخريطة ويتم حفظها مع المشروع الكامل؛ تجديد المنطقة يحل محلهم.",
    "Drag a road to move it. Drag a point to reshape it; double-click a point to remove it. Press Esc to finish.": "اسحب الطريق لتحريكه. اسحب نقطة لإعادة تشكيلها؛ انقر نقرًا مزدوجًا فوق نقطة لإزالتها. اضغط على Esc للإنهاء.",
    "Click to add points. Click the last point again or press Enter to finish; Esc cancels. Ends snap to junctions, settlements and roads.": "انقر لإضافة نقاط. انقر فوق النقطة الأخيرة مرة أخرى أو اضغط على Enter للإنهاء؛ إلغاء Esc. ينتهي بالانجذاب إلى التقاطعات والمستوطنات والطرق.",
    "Click a river. It is deleted together with every upstream tributary, its braids and its oxbows.": "انقر فوق النهر. فهو محذوف مع كل رافد منابعه وضفائره وأقواسه.",
    "Road {n}": "الطريق {n}",
