    "Road deleted.": "تم حذف الطريق.",
    "Road added.": "تمت إضافة الطريق.",
    "River deleted with {n} channels. Rebuild the towns on its banks to update their waterfront.": "تم حذف النهر بقنوات {n}. إعادة بناء المدن الواقعة على ضفافه لتحديث الواجهة البحرية.",
    "Create the terrain first.": "قم بإنشاء التضاريس أولاً.",
