    "Delete a river": "Удалить реку",
    "Choose a tool, then work on the map. Edits apply directly to this map and are saved with the complete project; regenerating the region replaces them.": "Выберите инструмент, затем работайте над картой. Изменения применяются непосредственно к этой карте и сохраняются вместе со всем проектом; регенерация региона заменяет их.",
    "Drag a road to move it. Drag a point to reshape it; double-click a point to remove it. Press Esc to finish.": "Перетащите дорогу, чтобы переместить ее. Перетащите точку, чтобы изменить ее форму; дважды щелкните точку, чтобы удалить ее. Нажмите Esc, чтобы закончить.",
    "Click to add points. Click the last point again or press Enter to finish; Esc cancels. Ends snap to junctions, settlements and roads.": "Нажмите, чтобы добавить баллы. Нажмите последнюю точку еще раз или нажмите Enter, чтобы закончить; Esc отменяет. Концы привязываются к перекресткам, населенным пунктам и дорогам.",
    "Click a river. It is deleted together with every upstream tributary, its braids and its oxbows.": "Нажмите на реку. Он удаляется вместе со всеми вышестоящими притоками, его косами и старицами.",
    "Road {n}": "Дорога {n}",
