    "Use current sites as list": "Использовать текущие сайты в качестве списка",
    "Roads enabled": "Дороги включены",
    "This diagnostic needs retained data from the selected water engine.": "Для этой диагностики необходимы сохраненные данные выбранного водяного двигателя.",
    "Fantasy · Ink (B&W)": "Фэнтези · Чернила (ч/б)",
    "Render v2 · Satellite": "Рендер v2 · Спутник",
    "Satellite trees": "Деревья-спутники",
    "Needs WebGPU, which this browser does not provide (see Settings).": "Требуется WebGPU, которого нет в этом браузере (см. Настройки).",
    "Needs the native Rust service, which is offline (see Settings).": "Нужен родной сервис Rust, который находится в автономном режиме (см. Настройки).",
    "Needs the Python/CUDA neural server, which is offline (see Settings).": "Требуется нейронный сервер Python/CUDA, который находится в автономном режиме (см. Настройки).",
    "The classic TypeScript engine only runs procedural relief on CPU.": "Классический движок TypeScript выполняет только процедурную разгрузку процессора.",
