    "Neural generation needs a GPU (WebGPU or a GPU service).": "Для генерации нейронных данных требуется графический процессор (WebGPU или служба графического процессора).",
    "Conflicts with an explicit GPU override below.": "Ниже приведены конфликты с явным переопределением графического процессора.",
