    "Redraw the retained map. These settings do not regenerate terrain or settlements.": "Перерисуйте сохраненную карту. Эти настройки не восстанавливают местность или поселения.",
    "Terrain and water layers": "Слои местности и воды",
    "Lighting and relief": "Освещение и рельеф",
    "Cities and buildings": "Города и здания",
    "Detailed city layers": "Подробные слои города",
