    "Terrain and water diagnostics": "Диагностика местности и воды",
    "Full quality": "Полное качество",
    "Light quality enabled to keep navigation fluid.": "Качество света позволило сохранить плавность навигации.",
    "Regional settlements and roads ready": "Готовы районные населенные пункты и дороги",
    "Loading model weights…": "Загрузка веса модели…",
    "Ready": "Готово",
    "The classic TypeScript engine supports 600–40,000 m. Select the Rust engine for 500–100,000 m.": "Классический движок TypeScript поддерживает 600–40 000 м. Выбирайте двигатель Rust на 500–100 000 м.",
    "CPU execution conflicts with explicit GPU terrain controls. Choose automatic/GPU or reset those controls.": "Выполнение ЦП конфликтует с явным контролем ландшафта графического процессора. Выберите автоматический/графический процессор или сбросьте эти элементы управления.",
    "GPU execution conflicts with explicit WASM CPU sampling. Choose automatic/CPU or reset the sampling control.": "Выполнение графического процессора конфликтует с явной выборкой ЦП WASM. Выберите автоматический/ЦП или сбросьте контроль выборки.",
    "GPU terrain generation requires GPU sampling. Select GPU FP32 or reset generation compute.": "Генерация ландшафта с помощью графического процессора требует выборки с помощью графического процессора. Выберите GPU FP32 или сбросьте вычисления генерации.",
