    "Prepare browser generation now. Downloads are shared with the terrain engine; no GPU is needed to download them.": "Подготовьте генерацию браузера прямо сейчас. Загрузки используются совместно с движком местности; для их загрузки не требуется графический процессор.",
    "Stored on this device, for this browser profile and site address. Clearing site data removes the models. These files do not install Python/CUDA models.": "Хранится на этом устройстве для этого профиля браузера и адреса сайта. При очистке данных сайта удаляются модели. Эти файлы не устанавливают модели Python/CUDA.",
    "Downloaded weights still need WebGPU and must be loaded into GPU memory at each new session. This does not make the whole application available offline.": "Загруженные веса по-прежнему нуждаются в WebGPU и должны загружаться в память графического процессора при каждом новом сеансе. Это не делает все приложение доступным в автономном режиме.",
    "NF4 B75 is the distilled base network: branch B, exponential moving-average weights at 75,000 training steps, 4-bit weight compression and a two-step solver. B75 names the training checkpoint.": "NF4 B75 — это дистиллированная базовая сеть: ветвь B, экспоненциальные веса скользящего среднего за 75 000 шагов обучения, 4-битное сжатие веса и двухэтапный решатель. B75 называет контрольную точку обучения.",
