    "Persistent storage granted. You can still remove models or clear site data.": "永続ストレージが付与されました。モデルを削除したり、サイト データをクリアしたりすることは可能です。",
    "Storage is not protected from automatic eviction. Request persistent storage to improve retention; the browser may refuse.": "ストレージは自動排除からは保護されません。保存期間を向上させるために永続ストレージをリクエストします。ブラウザが拒否する場合があります。",
    "Persistent storage requests are unavailable in this browser.": "このブラウザでは永続ストレージ リクエストは利用できません。",
    "The browser did not grant persistent storage. Downloaded files remain available but can be evicted.": "ブラウザは永続ストレージを許可しませんでした。ダウンロードされたファイルは引き続き利用可能ですが、削除することができます。",
